from PIL import Image
import glob

def analyze(fn):
    im = Image.open(fn).convert('RGB'); px = im.load()
    # cup top: average over columns 262-282 and 358-378
    tops=[]
    for x in list(range(262,283))+list(range(358,379)):
        for y in range(180,320):
            r,g,b = px[x,y]
            if r>100 and r-b>60:
                tops.append(y); break
    cup_top = sum(tops)/len(tops)
    # base bottom: columns 230-250, find last row with brightness<170 before bench
    bots=[]
    for x in range(225,255):
        prev=None
        for y in range(360,420):
            r,g,b=px[x,y]
            br=(r+g+b)/3
            if br>165 and prev is not None and prev<150:
                bots.append(y); break
            prev=br
    base_bot = sum(bots)/len(bots) if bots else None
    # spring dark region at x=320: rows between platen bottom and cup
    darks=[]
    for y in range(190,320):
        r,g,b=px[320,y]
        if r<90 and abs(r-g)<15 and abs(g-b)<20: darks.append(y)
    spring = (min(darks),max(darks),len(darks)) if darks else None
    return cup_top, base_bot, spring

for fn in sorted(glob.glob('captures/side_0*.jpg')):
    print(fn, analyze(fn))
EOF"}

