from PIL import Image
import glob
files = sorted(glob.glob('captures/side_0*.jpg'))
F=[4.62,8.60,12.64,16.76,20.97,25.30,29.68,34.82,40.21,44.94]
z=[97.128,96.782,96.428,96.067,95.698,95.321,94.936,94.483,94.012,93.598]

def prof(fn,x):
    im=Image.open(fn).convert('RGB'); px=im.load()
    return [(px[x,y][0]+px[x,y][1]+px[x,y][2])/3 for y in range(480)]

def edge(p, y0,y1, thresh, rising):
    for y in range(y0,y1):
        if rising and p[y]<thresh<=p[y+1]:
            return y+(thresh-p[y])/(p[y+1]-p[y])
        if not rising and p[y]>thresh>=p[y+1]:
            return y+(p[y]-thresh)/(p[y]-p[y+1])
    return None

for fn,f,zz in zip(files,F,z):
    p320=prof(fn,320); p270=prof(fn,270); p240=prof(fn,240)
    # platen bottom edge: light->dark between 205-225 at x=320
    pb=edge(p320,205,228,100,False)
    # seat: dark->yellow(rising brightness) between 245-265 at x=320
    st=edge(p320,245,268,90,True)
    # cup top at x=240: floor->yellow rising between 225-245
    ct=edge(p240,222,245,110,True)
    # base bottom at x=240: dark->bench rising 380-395
    bb=edge(p240,378,398,140,True)
    print(fn.split('/')[-1], "F=%5.2f z=%.3f platen=%.2f seat=%.2f cup=%.2f base=%.2f"%(f,zz,pb,st,ct,bb))
EOF"}

