from PIL import Image
files=['captures/side_%03d.jpg'%i for i in range(5,16)]
F=[4.62,8.60,12.64,16.76,20.97,25.30,29.68,34.82,40.21,44.94,47.1]
def col(fn,x):
    im=Image.open(fn).convert('RGB'); px=im.load()
    return [(px[x,y][0]+px[x,y][1]+px[x,y][2])/3 for y in range(480)]
def xe(p,y0,y1,t,rising):
    for y in range(y0,y1):
        a,b=p[y],p[y+1]
        if rising and a<t<=b: return y+(t-a)/(b-a)
        if not rising and a>t>=b: return y+(a-t)/(a-b)
    return float('nan')
for fn,f in zip(files,F):
    h=col(fn,150)   # horizon region far left
    s=col(fn,420)   # paper sign on bench (x~420, rows ~215-235?)
    # horizon: dark wall -> gray floor, find big rising step between 100-140
    hh=xe(h,95,140,60,True)
    # paper sign: floor->white rising 210-235
    ss=xe(s,205,240,150,True)
    print(fn[-7:-4],"F=%.1f horizon=%.2f sign=%.2f"%(f,hh,ss))
EOF

